package com.library.ui; import com.library.model.Transaction; import com.library.service.LibraryService; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*;
public class TransactionFrame extends JFrame { private final LibraryService service=new LibraryService();private final JTextField search=new JTextField(18);private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Member","Book","Issue","Due","Return","Fine","Status"},0){public boolean isCellEditable(int r,int c){return false;}}; public TransactionFrame(){super("Transactions");setSize(1050,600);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout());JPanel top=new JPanel(new BorderLayout());top.add(UI.header(this,"Transaction History","Search issued, returned and overdue library transactions"),BorderLayout.NORTH);JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,10,10));p.setBackground(Color.WHITE);p.add(new JLabel("Search by ID, member ID, book ID or status"));search.setPreferredSize(new Dimension(290,34));p.add(search);JButton b=UI.button("Search");b.addActionListener(e->load());p.add(b);top.add(p,BorderLayout.SOUTH);root.add(top,BorderLayout.NORTH);JTable table=new JTable(model);UI.table(table);root.add(new JScrollPane(table),BorderLayout.CENTER);add(root);load();} private void load(){try{model.setRowCount(0);for(Transaction t:service.transactions(search.getText()))model.addRow(new Object[]{t.getTransactionId(),t.getMemberName(),t.getBookName(),t.getIssueDate(),t.getDueDate(),t.getReturnDate(),UI.rupee(t.getFine()),t.getStatus()});}catch(Exception e){UI.error(this,e);}} }
